#!/usr/bin/env python3
"""Six distinct illustrated foundation covers. Deterministic; no network or AI at build time."""
from pathlib import Path
import base64,html,json
R=Path(__file__).resolve().parent.parent;P=R/'apps/web/public'
lines={'prompt':['AI, without','the guesswork'],'replies':['Your first business','assistant'],'sheets':['Make messy data','useful'],'web':['From idea to','working page'],'automation':['Automate the boring','bit—safely'],'cloud':['Understand the','AI plumbing']}
scenes={'prompt':'A tree of questions grows from a research notebook, surrounded by source cards and magnifying lenses.','replies':'A human shopkeeper reviews correspondence with a desk assistant before choosing a customer reply.','sheets':'Scattered receipts flow through a sorting machine into orderly data tiles and a chart.','web':'A human hand assembles a website as a tangible architectural model on a workbench.','automation':'A clockwork workflow routes envelopes through a review gate beside a human-operated safety stop.','cloud':'A terminal connects to cloud server chambers through glass pipes, authentication valves and a capacity reservoir.'}
for c in json.loads((P/'courses.json').read_text()):
 id=c['id'];data=base64.b64encode((R/'branding/build-path-art'/f'{id}.webp').read_bytes()).decode();e=lambda s:html.escape(s,quote=True)
 text=''.join(f'<text x="29" y="{380+i*37}" fill="#fff5e5" font-family="Georgia,serif" font-size="{29 if id in ["automation","replies"] else 33}" font-weight="bold">{e(t)}</text>' for i,t in enumerate(lines[id]))
 svg=f'''<svg xmlns="http://www.w3.org/2000/svg" width="410" height="520" viewBox="0 0 410 520" role="img" aria-labelledby="title desc"><title id="title">{e(c['title'])} — illustrated build path {c['num']}</title><desc id="desc">{e(scenes[id])} Original AI-generated editorial illustration, with authored title and instructional labels. Six guided activities.</desc><defs><linearGradient id="caption" x1="0" y1="0" x2="0" y2="1"><stop stop-color="#33241a" stop-opacity="0"/><stop offset=".4" stop-color="#33241a" stop-opacity=".9"/><stop offset="1" stop-color="#43180f"/></linearGradient></defs><rect width="410" height="520" fill="#7c1f16"/><image width="410" height="520" preserveAspectRatio="xMidYMid slice" href="data:image/webp;base64,{data}"/><rect x="18" y="18" width="374" height="43" rx="6" fill="#43180f" fill-opacity=".92"/><text x="30" y="36" fill="#f5d6a8" font-family="Arial,sans-serif" font-size="8" letter-spacing="1.4">THE OPEN PRACTICE COLLECTION</text><text x="30" y="51" fill="#fff5e5" font-family="Arial,sans-serif" font-size="9" font-weight="bold" letter-spacing="1">BUILD PATH {c['num']} / {e(c['track'].upper())}</text><rect y="285" width="410" height="235" fill="url(#caption)"/>{text}<path d="M29 439h352" stroke="#d9b78f" opacity=".65"/><text x="29" y="461" fill="#f5d6a8" font-family="Arial,sans-serif" font-size="9" letter-spacing="1.3">PRACTICAL AI ENGINEERING</text><text x="29" y="485" fill="#fff5e5" font-family="Georgia,serif" font-size="16">{c['num']} / Six guided activities</text><text x="29" y="504" fill="#d9b78f" font-family="Arial,sans-serif" font-size="7" letter-spacing="1">ORIGINAL AI-GENERATED ART · HUMAN-AUTHORED LESSONS</text></svg>'''
 (P/'brand/covers'/f'{id}.svg').write_text(svg)
print('Built six distinct full-colour foundation covers with embedded artwork and accessible descriptions.')
